column3:
AHOY() [
    COIN size!!

    ECHO("Enter size of Triangle: ")!!
    ASK("%C", @size)!!

    LOOK (size >=2 ) [

        HOIST (COIN i = 0!! i < size!! +#i) [ 
            HOIST (COIN j = 1!! j < size - i!! +#j) [
                ECHO(" ")!!
            ]
            HOIST (COIN k = 0!! k <= i!! +#k) [
                ECHO("* ")!!
            ]
            ECHO("\n")!!
        ]

    ] DROP [
        ECHO("\nInvalid Input: Size must be greater than one.\n")!!
    ]
]

AHOY() [
    COIN size, i!!
    ECHO("Enter size of Inverted Triangle: ")!!
    ASK("%C", @size)!!

    i = size!!

  LOOK (size >= 2) [

       HOIST (!! i > 0!! -#i) [       
          HOIST (COIN s = 0!! s < size - i!! +#s) [
            ECHO(" ")!!
          ]
          HOIST (COIN j = 0!! j < i!! +#j) [
            ECHO("* ")!!
          ]
          ECHO("\n")!!
        ]  
    ] DROP [
        ECHO("\nInvalid Input: Size must be greater than one.\n")!!
    ]
]

AHOY() [
    COIN size!!

    ECHO("Enter side length of Square: ")!!
    ASK("%C", @size)!!

     LOOK (size >= 2) [

        HOIST (COIN i = 0!! i < size!! +#i) [
        HOIST (COIN j = 0!! j < size!! +#j) [
            ECHO("*  ")!!
          ]
        ECHO("\n")!!
      ]

    ] DROP [
        ECHO("\nInvalid Input: Size must be greater than one.\n")!!
    ]

]

COIN n, even_sum = 0, odd_count = 0!!
DIME odd_sum = 0.0, odd_avg!!

AHOY() [
  ECHO("Enter N: ")!!
  ASK("%C", @n)!!

  LOOK(n > 1)[
    HOIST (COIN i = 1!! i <= n!! +#i) [
      LOOK (i % 2 == 0) [
        even_sum += i!!
      ] DROP [
        odd_sum += i!!
        odd_count += 1!!
      ]
    ]
  ] DROP [
    HOIST (COIN i = 1!! i >= n!! -#i) [
      LOOK (i % 2 == 0) [
        even_sum += i!!
      ] DROP [
        odd_sum += i!!
        odd_count += 1!!
      ]
    ]
  ]

  ECHO("Sum of even numbers from 1 to %C: %C\n", n, even_sum)!!

  LOOK (odd_count > 0) [
    odd_avg = odd_sum / odd_count!!
    ECHO("Average of odd numbers from 1 to %C: %D\n", n, odd_avg)!!
  ] DROP [
    ECHO("No odd numbers found in range.\n")!!
  ]
]
